-- ===== 20261028170000_h04_h06_commission_groups_visit_rate.sql =====
-- H04: business-configured commission groups/grades + explicit individual exceptions.
-- H06: inpatient doctor-visit incentive rate lives in commission settings (sumber visit_ranap).
-- No tariff is seeded. Null group keeps every legacy rule and employee unchanged.
-- Access (pay configuration, like H02): only OWNER may set an employee's commission group or
-- write rules that name an employee, a group, or an exception (no ADMIN self-raise). ADMIN keeps
-- general rules. Such rules are readable by OWNER/ADMIN/FINANCE only. Both tables already write
-- the A01 activity log, so every group change and every exception is recorded.

alter table public.employees
  add column if not exists commission_group varchar(40);
do $$ begin
  if not exists (select 1 from pg_constraint where conname = 'employees_commission_group_format') then
    alter table public.employees add constraint employees_commission_group_format
      check (commission_group ~ '^[a-z0-9][a-z0-9_-]{0,39}$');
  end if;
end $$;

alter table public.commission_rules
  add column if not exists commission_group varchar(40),
  -- Deleting a group rule deletes its exceptions: an orphaned exception must never become
  -- a standalone personal rule.
  add column if not exists override_group_rule_id uuid references public.commission_rules(id) on delete cascade;
do $$ begin
  if not exists (select 1 from pg_constraint where conname = 'commission_rules_group_format') then
    alter table public.commission_rules add constraint commission_rules_group_format
      check (commission_group ~ '^[a-z0-9][a-z0-9_-]{0,39}$');
  end if;
  if not exists (select 1 from pg_constraint where conname = 'commission_rule_override_scope_check') then
    alter table public.commission_rules add constraint commission_rule_override_scope_check
      check (override_group_rule_id is null or (employee_id is not null and commission_group is null));
  end if;
end $$;

comment on column public.employees.commission_group is
  'H04: kode grade/kelompok insentif yang ditetapkan bisnis. Null = tanpa kelompok.';
comment on column public.commission_rules.commission_group is
  'H04: aturan hanya berlaku untuk karyawan dengan kode kelompok ini. Null = tanpa batas kelompok.';
comment on column public.commission_rules.override_group_rule_id is
  'H04: pengecualian individu menggantikan aturan kelompok ini hanya pada baris yang cocok dengan keduanya.';

-- H06: 'visit_ranap' is 11 characters; widen before the new check.
alter table public.commission_rules drop constraint if exists commission_rules_sumber_check;
alter table public.commission_rules alter column sumber type varchar(16);
alter table public.commission_rules add constraint commission_rules_sumber_check
  check (sumber in ('semua', 'kasir', 'klinik', 'reseller', 'visit_ranap'));
do $$ begin
  if not exists (select 1 from pg_constraint where conname = 'commission_rules_visit_nominal_check') then
    alter table public.commission_rules add constraint commission_rules_visit_nominal_check
      check (sumber <> 'visit_ranap' or (tipe = 'nominal' and item_id is null and category_id is null));
  end if;
end $$;
comment on column public.commission_rules.sumber is
  'kasir = struk POS & online; klinik = tagihan kunjungan lunas; reseller = faktur B2B; semua = ketiganya (penjualan saja); '
  'visit_ranap = visit dokter rawat inap yang dikerjakan, nominal per visit, maks. 1 per dokter/rawat inap/tanggal WIB.';

-- H06 report reads visit logs by kind and time.
create index if not exists inpatient_daily_logs_doctor_visit_idx
  on public.inpatient_daily_logs (created_at, visit_doctor_id)
  where log_kind = 'doctor_visit';

-- H04 access: commission group is OWNER-only pay configuration (DB-enforced; the server
-- action guard is not the only line of defence).
create or replace function public.guard_employee_commission_group() returns trigger
language plpgsql security definer set search_path = '' as $$
begin
  if coalesce(auth.role(), '') = 'authenticated'
     and new.commission_group is distinct from (case when tg_op = 'UPDATE' then old.commission_group end)
     and not private.is_hris_owner() then
    raise exception using errcode = '42501', message = 'ACCESS_DENIED: kelompok komisi hanya dapat diubah OWNER';
  end if;
  return new;
end $$;
revoke all on function public.guard_employee_commission_group() from public, anon, authenticated, service_role;
drop trigger if exists h04_commission_group_owner on public.employees;
create trigger h04_commission_group_owner before insert or update of commission_group on public.employees
  for each row execute function public.guard_employee_commission_group();

drop policy if exists commission_rules_select_all on public.commission_rules;
drop policy if exists commission_rules_select_general on public.commission_rules;
drop policy if exists commission_rules_write_admin on public.commission_rules;
drop policy if exists commission_rules_write_owner on public.commission_rules;
drop policy if exists commission_rules_write_admin_general on public.commission_rules;
-- General rules stay readable by every signed-in account (unchanged); personal/group/exception
-- rules reveal individual pay and are readable by OWNER/ADMIN/FINANCE only.
create policy commission_rules_select_general on public.commission_rules
  for select to authenticated
  using ((employee_id is null and commission_group is null and override_group_rule_id is null)
    or (select private.hris_role()) in ('OWNER', 'ADMIN', 'FINANCE'));
create policy commission_rules_write_owner on public.commission_rules
  for all to authenticated
  using ((select private.is_hris_owner())) with check ((select private.is_hris_owner()));
create policy commission_rules_write_admin_general on public.commission_rules
  for all to authenticated
  using ((select private.hris_role()) = 'ADMIN' and employee_id is null and commission_group is null and override_group_rule_id is null)
  with check ((select private.hris_role()) = 'ADMIN' and employee_id is null and commission_group is null and override_group_rule_id is null);

-- ===== 20261028170500_h06_doctor_visit_tamper_guard.sql =====
-- H06: the doctor-visit incentive pays from inpatient_daily_logs rows with log_kind='doctor_visit'.
-- Those rows must not be steerable from the browser:
--  * on save, a visit's time is the server's time (any client created_at/log_date is replaced);
--  * after save, only OWNER/ADMIN may change a visit's time, date, doctor or kind (also turning a
--    monitoring note into a visit or a visit into a monitoring note). Everyone else is refused.
-- Monitoring notes keep their current behaviour (backdated entry still allowed). Edits remain
-- audited by audit_inpatient_care_edit (before-row + reason).
create or replace function public.guard_inpatient_doctor_visit() returns trigger
language plpgsql security definer set search_path = '' as $$
begin
  if tg_op = 'INSERT' then
    if new.log_kind = 'doctor_visit' then
      new.created_at := now();
      new.log_date := (now() at time zone 'Asia/Jakarta')::date;
    end if;
    return new;
  end if;
  if (old.log_kind = 'doctor_visit' or new.log_kind = 'doctor_visit')
     and (new.created_at is distinct from old.created_at or new.log_date is distinct from old.log_date
       or new.visit_doctor_id is distinct from old.visit_doctor_id or new.log_kind is distinct from old.log_kind)
     and coalesce(auth.role(), '') = 'authenticated'
     and coalesce(private.hris_role(), '') not in ('OWNER', 'ADMIN') then
    raise exception using errcode = 'P0001',
      message = 'ACCESS_DENIED: waktu, dokter, atau jenis visit dokter hanya dapat dikoreksi OWNER/ADMIN';
  end if;
  return new;
end $$;
revoke all on function public.guard_inpatient_doctor_visit() from public, anon, authenticated, service_role;
drop trigger if exists h06_doctor_visit_guard on public.inpatient_daily_logs;
create trigger h06_doctor_visit_guard before insert or update on public.inpatient_daily_logs
  for each row execute function public.guard_inpatient_doctor_visit();

-- ===== 20261028171000_h05_clinic_package_origin.sql =====
-- H05: clinic invoice lines that come from a package carry their package origin.
-- A tagged line is a package component: commission/omzet count it under the package
-- (qty = package qty), never as a normal SKU sale. Retail already sells a package as
-- one "Grup" line with its components in sale_item_group_components, so POS is unchanged.
-- Untagged lines (all historic lines) behave exactly as before. No stock/HPP/GL change.

alter table public.invoice_items
  add column if not exists package_item_id uuid references public.items(id) on delete restrict,
  add column if not exists package_qty numeric(15,4);
do $$ begin
  if not exists (select 1 from pg_constraint where conname = 'invoice_items_package_origin_pair') then
    alter table public.invoice_items add constraint invoice_items_package_origin_pair
      check ((package_item_id is null and package_qty is null) or (package_item_id is not null and package_qty > 0));
  end if;
end $$;
create index if not exists invoice_items_package_item_idx on public.invoice_items(package_item_id)
  where package_item_id is not null;
comment on column public.invoice_items.package_item_id is
  'H05: paket (barang Grup) asal baris komponen ini. Null = penjualan SKU biasa.';
comment on column public.invoice_items.package_qty is
  'H05: jumlah paket yang dijual untuk asal ini; aturan komisi paket menghitung qty ini.';

-- Server-side guard: the package must be an active Grup whose recipe contains the line SKU,
-- and the line quantity must be exactly package qty x recipe quantity (in base units), so a
-- cashier cannot inflate package qty for commission. A plain package line and tagged
-- components of the same package on one invoice are refused (that would count omzet twice).
-- Corrections and reissues inherit the exact source line tag, like the line seller.
create or replace function public.guard_clinic_line_package() returns trigger
language plpgsql security definer set search_path = '' as $$
declare v_source public.invoice_items%rowtype; v_recipe_base numeric; v_line_base numeric;
begin
  if tg_op = 'UPDATE' then
    if new.package_item_id is distinct from old.package_item_id or new.package_qty is distinct from old.package_qty then
      raise exception using errcode = 'P0001', message = 'CARE_INVALID: asal paket baris tersimpan tidak dapat ditulis ulang';
    end if;
    return new;
  end if;
  if new.package_item_id is null and new.service_source_line_id is not null then
    select * into v_source from public.invoice_items where id = new.service_source_line_id for share;
    if found and v_source.package_item_id is not null and v_source.item_id is not distinct from new.item_id then
      new.package_item_id := v_source.package_item_id;
      new.package_qty := v_source.package_qty;
    end if;
  end if;
  if new.package_item_id is null then
    new.package_qty := null;
    -- A plain package (Grup) line next to components already tagged with that package.
    if new.item_id is not null and exists(select 1 from public.invoice_items x
        where x.invoice_id = new.invoice_id and x.package_item_id = new.item_id) then
      raise exception using errcode = 'P0001', message = 'CARE_INVALID: paket ini sudah ditagih lewat komponennya di invoice yang sama';
    end if;
    return new;
  end if;
  if exists(select 1 from public.invoice_items x where x.invoice_id = new.invoice_id and x.item_id = new.package_item_id) then
    raise exception using errcode = 'P0001', message = 'CARE_INVALID: paket ini sudah ditagih sebagai satu baris di invoice yang sama';
  end if;
  if new.package_qty is null or new.package_qty <= 0 then
    raise exception using errcode = 'P0001', message = 'CARE_INVALID: jumlah paket wajib lebih dari 0';
  end if;
  if new.item_id is null then
    raise exception using errcode = 'P0001', message = 'CARE_INVALID: komponen paket harus barang dari master';
  end if;
  select sum(c.qty * c.factor) into v_recipe_base from public.items g
    join public.item_group_components c on c.group_item_id = g.id and c.component_item_id = new.item_id
    where g.id = new.package_item_id and g.item_type = 'Grup' and g.is_active;
  if v_recipe_base is null then
    raise exception using errcode = 'P0001', message = 'CARE_INVALID: barang ini bukan komponen paket aktif yang dipilih';
  end if;
  v_line_base := new.qty * coalesce(new.faktor, 1);
  if abs(v_line_base - new.package_qty * v_recipe_base) > 0.0001 then
    raise exception using errcode = 'P0001',
      message = format('CARE_INVALID: jumlah komponen harus %s (jumlah paket x isi resep), bukan %s', trim_scale(new.package_qty * v_recipe_base), trim_scale(v_line_base));
  end if;
  return new;
end $$;
revoke all on function public.guard_clinic_line_package() from public, anon, authenticated, service_role;
drop trigger if exists clinic_line_package on public.invoice_items;
create trigger clinic_line_package before insert or update on public.invoice_items
  for each row execute function public.guard_clinic_line_package();

-- Keep the atomic RPC signature/ACL; only carry the two optional line fields through.
-- Fail closed if the definition drifted from the reviewed text.
do $patch$
declare p record; definition text; signature regprocedure;
begin
  signature := to_regprocedure('public.clinic_post_invoice(uuid,text,jsonb,jsonb)');
  if signature is null then raise exception 'H05 missing required RPC clinic_post_invoice'; end if;
  definition := pg_get_functiondef(signature);
  if position('package_item_id' in definition) > 0 then return; end if; -- already applied
  for p in select * from (values
    (E'service_performers, bmhp_components, salesperson_id\n    ) values',
     E'service_performers, bmhp_components, salesperson_id, package_item_id, package_qty\n    ) values'),
    (E'v_bmhp, nullif(v_line.value->>''salesperson_id'','''')::uuid\n    ) returning',
     E'v_bmhp, nullif(v_line.value->>''salesperson_id'','''')::uuid,\n      nullif(v_line.value->>''package_item_id'','''')::uuid, nullif(v_line.value->>''package_qty'','''')::numeric\n    ) returning')
  ) as patches(old_text, new_text) loop
    if (length(definition) - length(replace(definition, p.old_text, ''))) / length(p.old_text) <> 1 then
      raise exception 'H05 expected exactly one anchor in clinic_post_invoice: %', left(p.old_text, 60);
    end if;
    definition := replace(definition, p.old_text, p.new_text);
  end loop;
  execute definition;
end $patch$;

-- ===== 20261028173000_h03_turnover_salary_components.sql =====
-- H03 (carried over from draft #229): salary components that pay a configured percentage
-- of posted net turnover (after discount and returns). Existing fixed components keep
-- their behaviour. No rate is seeded. Access stays as 20261027030000: salary_components
-- and employee_salary_components are OWNER-write, FINANCE-read.
alter table public.salary_components
  add column if not exists calculation_basis text not null default 'fixed',
  add column if not exists sales_source text not null default 'semua',
  add column if not exists sales_scope text not null default 'employee',
  add column if not exists rate_percent numeric(8,4) not null default 0;
do $$ begin
  if not exists (select 1 from pg_constraint where conname = 'salary_components_calculation_basis_check') then
    alter table public.salary_components add constraint salary_components_calculation_basis_check
      check (calculation_basis in ('fixed', 'net_turnover'));
  end if;
  if not exists (select 1 from pg_constraint where conname = 'salary_components_sales_source_check') then
    alter table public.salary_components add constraint salary_components_sales_source_check
      check (sales_source in ('semua', 'kasir', 'klinik', 'reseller'));
  end if;
  if not exists (select 1 from pg_constraint where conname = 'salary_components_sales_scope_check') then
    alter table public.salary_components add constraint salary_components_sales_scope_check
      check (sales_scope in ('employee', 'own_branch', 'all_branches'));
  end if;
  if not exists (select 1 from pg_constraint where conname = 'salary_components_turnover_rate_check') then
    alter table public.salary_components add constraint salary_components_turnover_rate_check
      check (rate_percent >= 0 and rate_percent <= 100 and (calculation_basis = 'fixed' or rate_percent > 0));
  end if;
end $$;

alter table public.employee_salary_components
  add column if not exists rate_percent_override numeric(8,4);
do $$ begin
  if not exists (select 1 from pg_constraint where conname = 'employee_salary_components_rate_override_check') then
    alter table public.employee_salary_components add constraint employee_salary_components_rate_override_check
      check (rate_percent_override is null or (rate_percent_override > 0 and rate_percent_override <= 100));
  end if;
end $$;

comment on column public.salary_components.calculation_basis is
  'fixed = nominal; net_turnover = rate_percent x omzet neto terposting (setelah diskon dan retur).';
comment on column public.salary_components.sales_scope is
  'employee = baris milik karyawan; own_branch = semua baris cabang karyawan; all_branches = semua baris sumber itu.';

alter table public.payrolls
  add column if not exists component_breakdown jsonb not null default '[]'::jsonb;
do $$ begin
  if not exists (select 1 from pg_constraint where conname = 'payrolls_component_breakdown_array') then
    alter table public.payrolls add constraint payrolls_component_breakdown_array
      check (jsonb_typeof(component_breakdown) = 'array');
  end if;
end $$;
comment on column public.payrolls.component_breakdown is
  'Snapshot komponen saat gaji dihitung: nama, asal (template/individu), dasar omzet, tarif, nominal.';

-- ===== 20261028174000_h02_payslip_templates.sql =====
-- H02: payslip templates per employee group (e.g. groomer, senior doctor).
-- A template lists salary components with optional template amounts/rates. Each employee
-- is linked to at most one template. Per-employee exceptions stay in
-- employee_salary_components (explicit row on the same component), and every link or
-- exception change is written to an append-only history with who/when/why.
-- No template, component or amount is seeded. Access mirrors 20261027030000:
-- OWNER manages pay configuration, FINANCE reads it, nobody else sees it.

create table if not exists public.payslip_templates (
  id uuid primary key default gen_random_uuid(),
  kode varchar(40) not null unique check (kode ~ '^[a-z0-9][a-z0-9_-]{0,39}$'),
  nama varchar(80) not null check (length(btrim(nama)) > 0),
  created_at timestamptz not null default now(),
  created_by uuid default auth.uid()
);

create table if not exists public.payslip_template_components (
  id uuid primary key default gen_random_uuid(),
  template_id uuid not null references public.payslip_templates(id) on delete cascade,
  component_id uuid not null references public.salary_components(id) on delete restrict,
  -- Null = follow the component master. Fixed components use nominal, turnover components rate.
  nominal numeric(15,2) check (nominal is null or nominal >= 0),
  rate_percent numeric(8,4) check (rate_percent is null or (rate_percent > 0 and rate_percent <= 100)),
  created_at timestamptz not null default now(),
  unique (template_id, component_id)
);
create index if not exists payslip_template_components_component_idx on public.payslip_template_components(component_id);

create table if not exists public.employee_payslip_templates (
  id uuid primary key default gen_random_uuid(),
  employee_id uuid not null unique references public.employees(id) on delete cascade,
  template_id uuid not null references public.payslip_templates(id) on delete restrict,
  updated_at timestamptz not null default now(),
  updated_by uuid default auth.uid()
);
create index if not exists employee_payslip_templates_template_idx on public.employee_payslip_templates(template_id);

alter table public.employee_salary_components
  add column if not exists override_reason text;
comment on column public.employee_salary_components.override_reason is
  'H02: alasan pengecualian bila komponen ini menimpa nilai dari template karyawan.';

create table if not exists public.payslip_override_history (
  id uuid primary key default gen_random_uuid(),
  employee_id uuid not null references public.employees(id) on delete cascade,
  action text not null check (action in ('template_set', 'template_removed', 'component_set', 'component_removed')),
  template_id uuid,
  component_id uuid,
  old_value jsonb,
  new_value jsonb,
  reason text,
  changed_by uuid default auth.uid(),
  changed_at timestamptz not null default now()
);
create index if not exists payslip_override_history_employee_idx on public.payslip_override_history(employee_id, changed_at desc);

create or replace function public.record_payslip_override_history() returns trigger
language plpgsql security definer set search_path = '' as $$
begin
  if tg_table_name = 'employee_payslip_templates' then
    if tg_op = 'DELETE' then
      insert into public.payslip_override_history(employee_id, action, template_id, old_value)
      values (old.employee_id, 'template_removed', old.template_id, jsonb_build_object('template_id', old.template_id));
      return old;
    end if;
    if tg_op = 'UPDATE' and new.template_id is not distinct from old.template_id then return new; end if;
    insert into public.payslip_override_history(employee_id, action, template_id, old_value, new_value)
    values (new.employee_id, 'template_set', new.template_id,
      case when tg_op = 'UPDATE' then jsonb_build_object('template_id', old.template_id) end,
      jsonb_build_object('template_id', new.template_id));
    return new;
  end if;
  -- employee_salary_components
  if tg_op = 'DELETE' then
    insert into public.payslip_override_history(employee_id, action, component_id, old_value, reason)
    values (old.employee_id, 'component_removed', old.component_id,
      jsonb_build_object('nominal', old.nominal, 'rate_percent_override', to_jsonb(old) -> 'rate_percent_override'), old.override_reason);
    return old;
  end if;
  if tg_op = 'UPDATE' and new.nominal is not distinct from old.nominal
    and (to_jsonb(new) -> 'rate_percent_override') is not distinct from (to_jsonb(old) -> 'rate_percent_override')
    and new.override_reason is not distinct from old.override_reason then
    return new;
  end if;
  insert into public.payslip_override_history(employee_id, action, component_id, old_value, new_value, reason)
  values (new.employee_id, 'component_set', new.component_id,
    case when tg_op = 'UPDATE' then jsonb_build_object('nominal', old.nominal, 'rate_percent_override', to_jsonb(old) -> 'rate_percent_override') end,
    jsonb_build_object('nominal', new.nominal, 'rate_percent_override', to_jsonb(new) -> 'rate_percent_override'),
    new.override_reason);
  return new;
end $$;
revoke all on function public.record_payslip_override_history() from public, anon, authenticated, service_role;
drop trigger if exists h02_payslip_history on public.employee_payslip_templates;
create trigger h02_payslip_history after insert or update or delete on public.employee_payslip_templates
  for each row execute function public.record_payslip_override_history();
drop trigger if exists h02_payslip_history on public.employee_salary_components;
create trigger h02_payslip_history after insert or update or delete on public.employee_salary_components
  for each row execute function public.record_payslip_override_history();

alter table public.payslip_templates enable row level security;
alter table public.payslip_template_components enable row level security;
alter table public.employee_payslip_templates enable row level security;
alter table public.payslip_override_history enable row level security;
revoke all on public.payslip_templates, public.payslip_template_components,
  public.employee_payslip_templates, public.payslip_override_history from anon;
grant select, insert, update, delete on public.payslip_templates, public.payslip_template_components,
  public.employee_payslip_templates to authenticated;
revoke all on public.payslip_override_history from authenticated;
grant select on public.payslip_override_history to authenticated;

do $$
declare t text;
begin
  foreach t in array array['payslip_templates', 'payslip_template_components', 'employee_payslip_templates'] loop
    execute format('drop policy if exists %I on public.%I', t || '_owner_all', t);
    execute format('drop policy if exists %I on public.%I', t || '_select_finance', t);
    execute format('create policy %I on public.%I for all to authenticated using ((select private.is_hris_owner())) with check ((select private.is_hris_owner()))', t || '_owner_all', t);
    execute format('create policy %I on public.%I for select to authenticated using ((select private.can_read_hris_money()))', t || '_select_finance', t);
  end loop;
end $$;
-- History is written only by the trigger above; OWNER/FINANCE read it.
drop policy if exists payslip_override_history_select on public.payslip_override_history;
create policy payslip_override_history_select on public.payslip_override_history
  for select to authenticated using ((select private.can_read_hris_money()));

commit;
